-- Cache of ALL reactions from the OdanLab project (149 total, generated 2026-09-30).
-- Not shown on the site by default. Lets the 'add by code' button on add.html
-- look up a reaction by its short code (e.g. AAP-36) and prefill the add form
-- without needing to ask Claude each time.
--
-- Run this once in Supabase's SQL Editor (same place you ran supabase-schema.sql).

create table if not exists public.odanlab_cache (
  code text primary key,
  reaction_id text,
  name text,
  reagents text,
  yield_analyt double precision,
  already_tracked boolean default false,
  created_at timestamptz
);

alter table public.odanlab_cache enable row level security;
create policy "odanlab_cache is readable by anyone with the anon key"
  on public.odanlab_cache for select to anon using (true);

-- Wipe and reload every time this file is regenerated (safe: this table is just
-- a read-only lookup cache, never the source of truth for what's on the site).
truncate table public.odanlab_cache;

